 */
public function shiftTimezone(DateTimeZone|string|int $timezone): static
{
    $this->timezoneSetting = $timezone;
    $this->checkStartAndEnd();

    if ($this->startDate) {
        $this->startDate = $this->startDate
            ->avoidMutation()
            ->shiftTimezone($timezone);
        $this->rawInterval = null;
    }

    if ($this->endDate) {
