 *                               current class
 *
 * @return static
 */
public static function instance(DateInterval $interval, array $skip = [], bool $skipCopy = false): static
{
    if ($skipCopy && $interval instanceof static) {
        return $interval;
    }

    return self::castIntervalToClass($interval, static::class, $skip);
}

/**
